// === Tab: mySketch ===
var PAD = 50;
var SZE = 25;

function setup() {
  const maxX = ~~((windowWidth - PAD - PAD) / SZE) * SZE + PAD + PAD;
  const maxY = ~~((windowHeight - PAD - PAD) / SZE) * SZE + PAD + PAD;
  createCanvas(maxX, maxY);
  describe("grid of diagonal lines based on noise");
  frameRate(1);

  stroke("black");
  strokeWeight(SZE/10);
}

function draw() {
  background("beige");

  for (let y = PAD + SZE / 2; y <= height - SZE / 2 - PAD; y += SZE) {
    for (let x = PAD + SZE / 2; x <= width - SZE / 2 - PAD; x += SZE) {
      drawShape(x, y, SZE);
    }
  }
}

function drawShape(x, y, s) {
  push();
  translate(x, y);

  const n = noise(x, y, frameCount);
  if (n < 0.5) {
    // nothing
  } else if (n < 0.55) {
    line(-s/2, -s/2, s/2, s/2);
  } else if (n < 0.6) {
    line(s/2, -s/2, -s/2, s/2);
  } else {
    line(-s/2, -s/2, s/2, s/2);
    line(s/2, -s/2, -s/2, s/2);
  }

  pop();
}

function mousePressed() {
  if (mouseButton === LEFT) setup();
}
